export const MONUMENTS = JSON.parse("[{\"id\":\"n1290022208\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"В. М. Жирмунскому\",\"x\":-360.4,\"z\":604.7,\"subject\":\"Q120572\",\"inscription\":\"В этом доме с 1951 по 1971 год жил и работал выдающийся филолог академик Виктор Максимович Жирмунский\"},{\"id\":\"n1295296070\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"В. В. Капнисту\",\"x\":-456.4,\"z\":680.7,\"subject\":\"Q713704\",\"inscription\":\"В этом доме в 1790-1793 годы жил поэт драматург переводчик Василий Васильевич Капнист\"},{\"id\":\"n9784449095\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"Л. К. Чуковской и М. П. Бронштейну\",\"x\":-470.3,\"z\":661.1,\"subject\":\"Q433942;Q1226083\",\"inscription\":\"В этом доме с сентября 1935 года жили: до мая 1941 года писательница Лидия Корнеевна Чуковская /1907-1996/, до ареста в августе 1937 года физик-теоретик Матвей Петрович Бронштейн /1906-1938, расстрелян/. Здесь в 1939-40 была написана \\\"Софья Петровна\\\"...\"},{\"id\":\"n9805904775\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"А. Г. Рубинштейну\",\"x\":-468.5,\"z\":602.8,\"subject\":\"Q87567\"},{\"id\":\"n10161916702\",\"kind\":\"artwork\",\"sub\":\"installation\",\"x\":-490.1,\"z\":674.6,\"description\":\"Следы от обуви\"},{\"id\":\"n11966405496\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"Дмитрий Васильевич Григорович\",\"x\":-2395.8,\"z\":623,\"inscription\":\"Дом, где в 1893-1899 гг. жил и умер писатель Дмитрий Васильевич Григорович\"},{\"id\":\"n12007301467\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"Ф. М. Достоевскому\",\"x\":-2159.9,\"z\":617.1,\"inscription\":\"В этом доме в 1864-1867 годах жил Федор Михайлович Достоевский. Здесь написан роман \\\"Преступление и наказание\\\"\"},{\"id\":\"n11178184224\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"П.А. Бринько\",\"x\":-1905.3,\"z\":736,\"material\":\"granite\",\"inscription\":\"Петр Антонович Бринько 1915-1941 Герой Советского Союза, летчик-истребитель бригады ВВС Балтийского Флота, участвовал в обороне Ленинграда, Таллина, полуострова Ханко\"},{\"id\":\"n1312089863\",\"kind\":\"memorial\",\"sub\":\"bust\",\"name\":\"Н. А. Панин-Коломенкин\",\"x\":-3411.8,\"z\":705.4,\"subject\":\"Q984655\",\"inscription\":\"Николай Александрович Панин-Коломенкин 1872–1956 Первый российский Олимпийский Чемпион (1908 год, Лондон), выступал в фигурном катании на коньках. Заслуженный Мастер спорта СССР. Кандидат педагогических наук.\"},{\"id\":\"n1244913803\",\"kind\":\"memorial\",\"sub\":\"statue\",\"name\":\"Н. А. Римский-Корсаков\",\"x\":-3025.9,\"z\":661.5,\"subject\":\"Q93227\",\"inscription\":\"Николаю Андреевичу Римскому-Корсакову. 1844—1908\",\"wikidata\":\"Q4343330\",\"wikipedia\":\"ru:Памятник Римскому-Корсакову\"},{\"id\":\"n6025004488\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"Д. В. Наливкину\",\"x\":-3160.9,\"z\":616.2,\"subject\":\"Q1232728\",\"inscription\":\"Здесь с 1946 по 1982 год жил выдающийся советский геолог, Герой Социалистического Труда, лауреат Ленинской премии и Государственной премии СССР академик Дмитрий Васильевич Наливкин (1889-1982)\"},{\"id\":\"n6025004489\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"И. Ф. Стравинскому\",\"x\":-3155.3,\"z\":634.7,\"subject\":\"Q7314\",\"inscription\":\"В этом доме с 1882 по 1908 год жил и работал выдающийся русский композитор Игорь Фёдорович Стравинский\"},{\"id\":\"n6085656240\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"В. Э. Мейерхольду\",\"x\":-2949.5,\"z\":611.8,\"subject\":\"Q165721\",\"inscription\":\"В этом доме с 1909 по 1914 год жил известный советский режиссёр, народный артист республики Всеволод Эмильевич Мейерхольд\"},{\"id\":\"n10955345440\",\"kind\":\"artwork\",\"sub\":\"sculpture\",\"name\":\"Лев\",\"x\":-2793,\"z\":601.5,\"artist\":\"Павел Петрович Соколов\"},{\"id\":\"n10955345441\",\"kind\":\"artwork\",\"sub\":\"sculpture\",\"name\":\"Лев\",\"x\":-2795.1,\"z\":602.3,\"artist\":\"Павел Петрович Соколов\"},{\"id\":\"n10955345442\",\"kind\":\"artwork\",\"sub\":\"sculpture\",\"name\":\"Лев\",\"x\":-2784.8,\"z\":625.1,\"artist\":\"Павел Петрович Соколов\"},{\"id\":\"n10955345443\",\"kind\":\"artwork\",\"sub\":\"sculpture\",\"name\":\"Лев\",\"x\":-2782.8,\"z\":624.1,\"artist\":\"Павел Петрович Соколов\"},{\"id\":\"n6579113380\",\"kind\":\"memorial\",\"sub\":\"statue\",\"name\":\"В. И. Ленин\",\"x\":-3427.2,\"z\":621.9,\"subject\":\"Q1394\"},{\"id\":\"n6566664695\",\"kind\":\"memorial\",\"sub\":\"statue\",\"name\":\"О. Ф. Берггольц\",\"x\":-1481.8,\"z\":713.9,\"startDate\":\"1988-05-16\",\"subject\":\"Q237518\",\"artist\":\"Н. Г. Сухорукова\",\"wikidata\":\"Q113415278\",\"wikipedia\":\"ru:Памятник Ольге Берггольц (Гороховая улица)\"},{\"id\":\"n8942408504\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"Серафиму Вырицкому\",\"x\":-1216.5,\"z\":622.7,\"subject\":\"Q4416650\",\"inscription\":\"В этом доме с 1914 по 1917 год жил петербургский купец Василий Николаевич Муравьёв, в монашестве Серафим Вырицкий. Канонизирован Русской Православной Церковью в лике преподобных.\"},{\"id\":\"n8851230042\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"x\":-1056.7,\"z\":641.5,\"subject\":\"Q2072231\",\"inscription\":\"Переулок назван в честь великого казахского акына Жамбыла Жабаева (Джамбула), воспевшего подвиг ленинградцев в годы Великой Отечественной войны 1941-1945 г.г.\"},{\"id\":\"n11914860369\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"x\":-858.9,\"z\":686.6,\"inscription\":\"За благоустройство Лениграда.1968. Квартал II\"}]");
